  "A one-time code lets your phone or another computer sign in with a passkey of its own.": "លេខកូដតែមួយដងអាចឱ្យទូរសព្ទរបស់អ្នក ឬកុំព្យូទ័រផ្សេងទៀតចូលដោយប្រើលេខសម្ងាត់របស់វា។",
