  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "បញ្ជាក់។ ឥឡូវបង្កើតលេខសម្ងាត់ថ្មី; កម្មវិធីរុករករបស់អ្នកនឹងសួរកន្លែងដែលត្រូវរក្សាទុកវា។",
  "Copy link": "ចម្លងតំណ",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "បង្កើតលេខសម្ងាត់នៅលើឧបករណ៍នេះសម្រាប់កម្រងព័ត៌មាន “{0}” ។ វាចុះហត្ថលេខាអ្នកនៅទីនេះចាប់ពីពេលនេះតទៅ។",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "គ្នា​ចូល​ទៅ​កាន់​កម្រង​ព័ត៌មាន​នេះ​ពី​ឧបករណ៍ ឬ​កម្មវិធី​គ្រប់គ្រង​ពាក្យ​សម្ងាត់​ដែល​រក្សា​វា​ទុក។ ចុចមួយដើម្បីប្តូរឈ្មោះ ឬលុបវាចេញ។",
  "Enter the code from your other device.": "បញ្ចូលលេខកូដពីឧបករណ៍ផ្សេងទៀតរបស់អ្នក។",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "សម្រាប់ឧបករណ៍នេះ សោសុវត្ថិភាព អ្នកគ្រប់គ្រងពាក្យសម្ងាត់ ឬទូរសព្ទរបស់អ្នកតាមរយៈកូដ QR ផ្ទាល់ខ្លួនរបស់កម្មវិធីរុករកតាមអ៊ីនធឺណិត។ ដំបូង​ត្រូវ​បញ្ជាក់​ថា​ជា​អ្នក​។",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "វាមិនអាចចូលទម្រង់នេះទៀតទេ។ ឧបករណ៍​ដែល​បាន​ចូល​រួច​ហើយ​ជាមួយ​វា​នឹង​បន្ត​ចូល។ ប្រសិនបើ​វា​បាត់ សូម​ប្រើ​ចេញ​នៅ​គ្រប់​ទីកន្លែង។",
  "It is your only way in, so it cannot be removed until there is another.": "វាគឺជាផ្លូវតែមួយគត់របស់អ្នក ដូច្នេះវាមិនអាចដកចេញបានទេ រហូតដល់មានមួយទៀត។",
  "Last used {0}": "បានប្រើចុងក្រោយ {0}",
