  "None yet. Add one and sign in without your password.": "មិនទាន់មានទេ។ បន្ថែមមួយ ហើយចូលដោយគ្មានពាក្យសម្ងាត់របស់អ្នក។",
  "Passkey added": "លេខសម្ងាត់ត្រូវបានបន្ថែម",
