  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "ស្កេនវាជាមួយឧបករណ៍ផ្សេងទៀត ឬបើក OpenGym នៅទីនោះ ហើយបញ្ចូលលេខកូដនៅលើអេក្រង់ចូល។ វាដំណើរការម្តងក្នុងរយៈពេល {0} នាទី។",
  "That code is wrong, already used or expired. Make a new one on your other device.": "លេខកូដនោះខុស ប្រើរួចហើយ ឬផុតកំណត់។ បង្កើតឧបករណ៍ថ្មីមួយនៅលើឧបករណ៍ផ្សេងទៀតរបស់អ្នក។",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "កម្មវិធីរុករកតាមអ៊ីនធឺណិតនេះមិនអាចបញ្ជាក់ដោយប្រើលេខសម្ងាត់របស់អ្នកបានទេ។ ធ្វើដូចនេះនៅលើឧបករណ៍ដែលមានមួយ។",
  "First confirm that it is you.": "ដំបូង​ត្រូវ​បញ្ជាក់​ថា​ជា​អ្នក​។",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "កម្រងព័ត៌មាននេះមិនមានលេខសម្ងាត់ទេ ហើយម៉ាស៊ីនមេនេះមិនយកពាក្យសម្ងាត់ទេ ដូច្នេះគ្មានអ្វីនៅទីនេះអាចបញ្ជាក់ថាជាអ្នកនោះទេ។ សួរអ្នកគ្រប់គ្រងរបស់អ្នក។",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "កម្មវិធីរុករកតាមអ៊ីនធឺណិតនេះមិនអាចបង្កើតលេខសម្ងាត់បានទេ ដូច្នេះវាមិនអាចបន្ថែមដោយលេខកូដបានទេ។ បើកតំណនៅក្នុងកម្មវិធីរុករកដែលអាច។",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "កម្មវិធីរុករកតាមអ៊ីនធឺណិតនេះត្រូវបានចូលជា “{0}”។ ការបន្ថែមវាទៅ “{1}” ចុះហត្ថលេខា “{0}” នៅទីនេះ។",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "លេខកូដនេះគឺសម្រាប់កម្រងព័ត៌មានផ្សេងដែលត្រូវបានគេហៅថា “{0}” ផងដែរ មិនមែ���កម្មវិធីរុករកតាមអ៊ីនធឺណិតនេះត្រូវបានចូលនោះទេ។ បន្ថែមវានៅទីនោះ សញ្ញារបស់អ្នកចេញនៅទីនេះ។",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "បន្ត លុះត្រាតែលេខកូដនេះមកពីឧបករណ៍ផ្ទាល់ខ្លួនរបស់អ្នក។ បន្ទាប់មក កម្មវិធីរុករកតាមអ៊ីនធឺណិតនេះត្រូវបានចូល “{0}” ហើយអ្វីដែលអ្នកចូលនៅទីនេះគឺទៅកាន់កម្រងព័ត៌មាននោះ។",
  "This code has expired.": "លេខកូដនេ���បានផុតកំណត់ហើយ។",
