  "This passkey already belongs to a profile.": "លេខសម្ងាត់នេះជាកម្មសិទ្ធិរបស់កម្រងព័ត៌មានរួចហើយ។",
  "This profile already has as many passkeys as it can hold.": "កម្រង​ព័ត៌មាន​នេះ​មាន​លេខ​សម្ងាត់​ច្រើន​តាម​ដែល​វា​អាច​កាន់​បាន។",
  "Use a code from your other device": "ប្រើលេខកូដពីឧបករណ៍ផ្សេងទៀតរបស់អ្នក",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "អ្នកទទួលបានលេខកូដដែលអនុញ្ញាតឱ្យទូរស័ព្ទរបស់អ្នក ឬកុំព្យូទ័រផ្សេងទៀតបង្កើតលេខសម្ងាត់សម្រាប់កម្រងព័ត៌មាននេះ។ ដំបូង​ត្រូវ​បញ្ជាក់​ថា​ជា​អ្នក​។",
