  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "ពីរ​សិត​ជាប់​គ្នា បូក​រួម​នឹង​មួយ​សិត​ចុង​ក្រោយ​ត្រូវ​ទទួល​បរាជ័យ។ វាយគោលដៅលើឈុតនោះ ហើយទម្ងន់នឹងកើនឡើង (ពីរដងប្រសិនបើអ្នកធ្វើម្តងទៀតពីរដង) ។ ការបរាជ័យមួយកំណត់ឡើងវិញ 10% ។",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "ធ្វើការឡើងតាមរយៈជួរតំណាងដែលមានទម���ងន់ដូចគ្នា។ ឈានដល់កំពូលនៃជួរនៅគ្រប់ឈុត ហើយទម្ងន់នឹងឡើង ធ្វើម្តងទៀតទៅបាត។",
  "Hold every set for the full duration and the target goes up.": "សង្កត់រាល់ឈុតសម្រាប់រយៈពេលពេញ ហើយគោលដៅនឹងឡើង។",
  "Nothing logged yet, so this session sets the baseline.": "គ្មាន​អ្វី​បាន​ចូល​នៅ​ឡើយ​ទេ ដូច្នេះ​វគ្គ​នេះ​កំណត់​បន្ទាត់​មូលដ្ឋាន។",
  "Held every set for the full time. Target goes up by {0}s.": "រៀបចំគ្រប់ឈុតពេញម៉ោង។ គោលដៅកើនឡើងដោយ {0}s ។",
  "Short {0} sessions in a row. Back off to {1}s and build up again.": "វគ្គ {0} ខ្លីៗជាប់គ្នា។ ត្រលប់ទៅ {1}s ហើយបង្កើតម្តងទៀត។",
  "Came up short last time. Same target again.": "មក​ដល់​រយៈ​ពេល​ខ្លី។ គោលដៅដដែលម្តងទៀត។",
  "Top of the rep range in every set. {0} {1} more, back to {2} reps.": "កំពូលជួរតំណាងនៅក្នុងឈុតនីមួយៗ។ {0} {1} ទៀត ត្រលប់ទៅ {2} ដង។",
  "Stuck for {0} sessions. Deload to {1} {2}.": "ជាប់គាំងសម្រាប់ {0} វគ្គ។ ផ្ទុកទៅ {1} {2} ។",
  "Same weight, aim for {0} reps this time.": "ទម្ងន់ដូចគ្នា មានបំណងសម្រាប់ {0} ដងនៅពេលនេះ។",
  "Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.": "ឈុតចុងក្រោយប៉ះគ្នា {0} ដង គោលដៅពីរដង! លោតពីរដងនៃ {1} {2} ។",
  "Every rep last time. {0} {1} more.": "រាល់តំណាងកាលពីលើកមុន។ {0} {1} ទៀត។",
  "Every rep last time. {0} {1} less help.": "រាល់តំណាងកាលពីលើកមុន។ {0} {1} ជំនួយតិច។",
  "Top of the rep range in every set. {0} {1} less help, back to {2} reps.": "កំពូលជួរតំណាងនៅក្នុងឈុតនីមួយៗ។ ជំនួយតិច {0} {1} ត្រឡប់ទៅ {2} ដងវិញ។",
  "Missed reps. {0} {1} of help while you build back up.": "ខកខានតំណាងរាស្រ្ត។ ជំនួយ {0} {1} នៅពេលអ្នកបង្កើតការបម្រុងទុក។",
  "Stuck for {0} sessions. Back to {1} {2} of help, then build up again.": "ជាប់គាំងសម្រាប់ {0} វគ្គ។ ត្រលប់ទៅ {1} {2} នៃជំនួយ បន្ទាប់មកបង្កើតម្តងទៀត។",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "ខកខានតំណាងរាស្ដ្រ {0} វគ្គដែលកំពុងដំណើរការ។ កំណត់ឡើងវិញទៅ {1} {2} ហើយធ្វើការបម្រុងទុក។",
  "Missed reps. Reset to {0} {1} and work back up.": "ខកខានតំណាងរាស្រ្ត។ កំណត់ឡើងវិញទៅ {0} {1} ហើយធ្វើការបម្រុងទុក។",
  "Missed reps last time. Same weight again ({0} of {1} to go).": "ខកខានដងកាលពីលើកមុន។ ទម្ងន់ដូចគ្នាម្តងទៀត ({0} នៃ {1} ទៅ)។",
  "Bodyweight: every rep last time, so go for {0} this time.": "ទម្ងន់ខ្លួន៖ រាល់ដងលើកចុងក្រោយ ដូច្នេះសូមទៅ {0} លើកនេះ។",
  "Bodyweight: same target again until every set is clean.": "ទំងន់រាងកាយ៖ គោលដៅដដែលម្តងទៀតរហូតដល់រាល់ឈុតទាំងអស់ស្អាត។",
  "{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.": "ឈុត {0} នាំយក {1} មកជាមួយ។ បើកការខិតខំប្រឹងប្រែងក្នុងមួយឈុតក្នុងការកំណត់ដើម្បីមើលវា។",
  "{0} sets bring an {1} with them.": "ឈុត {0} នាំយក {1} មកជាមួយ។",
  "RIR": "RIR (កម្លាំងនៅសល់)",
