  "What are RIR and RPE?": "តើអ្វីទៅជា RIR និង RPE?",
  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "តើ​ឈុត​មួយ​មាន​ភាព​លំបាក​ប៉ុនណា​ ​ត្រូវ​កត់ត្រា​នៅ​ជាប់​នឹង​ទម្ងន់​ និង​តំណាង។ មាត្រដ្ឋានពីរសម្រាប់ការវិនិច្ឆ័យដូចគ្នា រាប់ពីចុងទល់មុខ។",
  "How it felt": "តើវាមានអារម្មណ៍យ៉ាងណា",
