  "Easy, warm-up territory": "ងាយស្រួល, ទឹកដីកក់ក្តៅ",
  "Maybe half a rep left": "ប្រហែលជានៅសល់កម្លាំងកន្លះដងទៀត",
  "How hard was that set?": "តើ​ឈុត​នោះ​ពិបាក​ប៉ុណ្ណា?",
  "Tap how many reps you had left, or type an exact {0}.": "ប៉ះចំនួនដងដែល��្នកបានចាកចេញ ឬវាយ {0} ពិតប្រាកដ។",
  "Exact {0}": "ពិតប្រាកដ {0}",
  "Clear rating": "ការវាយតម្លៃច្បាស់លាស់",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIR រាប់ចំនួនដងដែលអ្នកនៅសល់កម្លាំងអាចលើកបានទៀត (reps in reserve); RPE វាស់កម្រិតកម្លាំងដូចគ្នានៅលើមាត្រដ្ឋាន ១០ កម្រិត ដូច្នេះ RPE ≈ 10 − RIR។ ជ្រើសរើសប្រព័ន្ធណាដែលអ្នកធ្លាប់ប្រើ។",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "ជួរដែលបានបន្លិចគឺជាកន្លែងដែលការងារភាគច្រើនកំណត់ដី។ សំណុំដែលអ្នកបានចូលរួចហើយ រក្សាមាត្រដ្ឋានផ្ទាល់ខ្លួនរបស់ពួកគេ ហើយគ្មានអ្វីផ្សេងទៀតអានតម្លៃទេ ដូច្នេះការវិវឌ្ឍន៍ និងការប៉ាន់ប្រមាណ 1RM មិនរងផលប៉ះពាល់ទេ។",
