  "Could not generate a code": "មិនអាចបង្កើតលេខកូដបានទេ",
  "On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.": "នៅលើកម្មវិធី OpenGym សូមជ្រើសរើស “ភ្ជាប់ទៅម៉ាស៊ីនមេរបស់ខ្ញុំ” បន្ទា���់មកបញ្ចូលអាសយដ្ឋាននេះ និងលេខកូដខាងក្រោម។ វាផុតកំណត់ក្នុងរយៈពេល 5 នាទី។",
  "Enter your server address and the code": "បញ្ចូលអាសយដ្ឋានម៉ាស៊ីនមេ និងលេខកូដរបស់អ្នក",
  "Connected": "បានភ្ជាប់",
