  "Use on this device": "ប្រើនៅលើឧបករណ៍នេះ",
  "Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.": "ក្នុងស្រុករក្សាអ្វីគ្រប់យ៉ាងនៅលើទូរស័ព្ទនេះ។ ការភ្ជាប់ការធ្វើសមកាលកម្មទៅម៉ាស៊ីនមេ openGym ផ្ទាល់ខ្លួនរបស់អ្នកជំនួសវិញ។ អ្នកអាចប្តូរនៅពេលក្រោយនៅក្នុងការកំណត់។",
