  "Warm-up sets": "សិតកម្តៅសាច់ដុំ",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.": "បន្ថែមមុនពេលការងាររបស់អ្នកកំណត់ ហើយបានចាកចេញពីបរិមាណហ្វឹកហាត់ កំណត់ត្រា និងដំណើរការ។ នីមួយៗបិទគម្លាតពាក់កណ្តាលទៅនឹងទម្ងន់ការងារ មិនដែលនៅក្រោមរបារនៅលើការលើក barbell ទេ ហើយអ្នកនៅតែអាចផ្លាស់ប្តូរណាមួយក្នុងចំណោមពួកគេពាក់កណ្តាលវគ្គ។",
  "Ramp-up sets added before the work sets, so you do not have to add them by hand each session.": "សំណុំ​ការ​បង្កើន​ការ​បន្ថែម​មុន​នឹង​សំណុំ​ការងារ ដូច្នេះ​អ្នក​មិន​ចាំបាច���​បន្ថែម​ពួក​វា​ដោយ​ដៃ​រៀង​រាល់​វគ្គ​។",
  "Note": "ចំណាំ",
  "This session": "វគ្គនេះ",
