  "You can turn this off at any time, which also discards anything the Coach is holding for you.": "អ្នកអាចបិទវាបានគ្រប់ពេល ដែលនឹងបោះបង់អ្វីៗដែលគ្រូបង្វឹកកំពុងកាន់សម្រាប់អ្នក។",
  "The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "The Coach មិនមែនជាវេជ្ជបណ្ឌិត ឬគ្រូពេទ្យព្យាបាលរោគទេ។ ប្រសិនបើមានអ្វីឈឺសូមសួរអ្នកជំនាញ។",
  "Not now": "មិនមែនឥឡូវនេះទេ",
  "Meet the Coach": "ជួបជាមួយគ្រូបង្វឹក",
