  "An AI coach that can design your plan and adjust it from what you actually log. It runs with your own API key, it never changes anything without your say-so, and it is off until you turn it on.": "គ្រូបង្វឹក AI ដែលអាចរចនាផែនការរបស់អ្នក និងកែតម្រូវវាពីអ្វីដែលអ្នកពិតជាបានកត់ត្រា។ វាដំណើរការដោយប្រើសោ API ផ្ទាល់ខ្លួនរបស់អ្នក វាមិនផ្លាស់ប្តូរអ្វីទាំងអស់ដោយគ្មានការនិ���ាយរបស់អ្នក ហើយវាបិទរហូតដល់អ្នកបើកវា។",
