  "Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.": "ប្រព័ន្ធប្រតិបត្តិការ Android ទប់ស្កាត់ការភ្ជាប់ http:// ដែលមិនបានអ៊ិនគ្រីបពីកម្មវិធី ដូច្នេះទូរស័ព្ទនេះអាចទៅដល់ចំណុចបញ្ចប់ https:// ប៉ុណ្ណោះ។ ដាក់ ​​HTTPS នៅពីមុខវា (ខ្នាតកន្ទុយ ឬប្រូកស៊ីបញ្ច្រាស) ឬជ្រើសរើស \"ប្រើ OpenGym ដែលបង្ហោះដោយខ្លួនឯង\"៖ ម៉ាស៊ីនមេរបស់អ្នកអាចទៅដល់គំរូ http:// នៅលើបណ្តាញរបស់វា។",
  "Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.": "សំណើនីមួយៗទៅ {0} ដោយប្រើសោរបស់អ្នក។ គ្មាន​អ្នក​ណា​ឃើញ​វា​ទេ ហើយ​អ្នក​បង់​ថ្លៃ​វា។",
  "Endpoint": "ចំណុចបញ្ចប់",
