  "Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.": "ការងារភាគច្រើនបានបញ្ចប់។ មួយ​ឬ​ពីរ​ឈុត​បាន​ធ្លាក់​ចុះ​ខ្លី ដែល​ល្អ​ម្តង។ វាគ្រាន់តែជាសញ្ញាមួយប៉ុណ្ណោះ ប្រសិនបើឈុតដូចគ្នាខកខានលើកក្រោយ។",
