  "This phone is no longer paired with your server. Your changes are kept here.": "ទូរសព្ទនេះមិនត្រូវបានផ្គូផ្គងជាមួយម៉ាស៊ីនមេរបស់អ្នកទៀតទេ។ ការផ្លាស់ប្តូររបស់អ្នកត្រូវបានរក្សាទុកនៅទីនេះ។",
