  "Couldn’t keep a copy of the changes on this device. Nothing was removed.": "មិនអាចរក្សាច្បាប់ចម្លងនៃការផ្លាស់ប្តូរនៅលើឧបករណ៍នេះបានទេ។ គ្មានអ្វីត្រូវបានដកចេញទេ។",
  "Not everything is on your server yet": "មិនទាន់មានអ្វីគ្រប់យ៉ាងនៅលើម៉ាស៊ីនមេរបស់អ្នកនៅឡើយទេ",
  "Not on your server yet: {0}": "មិនមាននៅលើម៉ាស៊ីនមេរបស់អ្នកនៅឡើយទេ៖ {0}",
  "Some changes on this device have not reached your server.": "ការផ្លាស់ប្តូរមួយចំនួននៅលើឧបករណ៍នេះមិនទាន់បានទៅដល់ម៉ាស៊ីនមេរបស់អ្នកទេ។",
  "Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "ព្យាយាមម្តងទៀត ឬនាំចេញការបម្រុងទុកជាមុនសិន។ បន្តទៅមុខទៀត រក្សាច្បាប់ចម្លងនៃការផ្លាស់ប្តូរទាំងនេះនៅលើឧបករណ៍នេះ រហូតដល់វាភ្ជាប់ទៅម៉ាស៊ីនមេនេះជាគណនីនេះម្តងទៀត។ បន្ទាប់មកពួកគេត្រូវបានបន្ថែមត្រឡប់មកវិញ។",
