  "Server & sync": "ម៉ាស៊ីនមេ & សមកាលកម្ម",
  "Signed in as {0}": "បានចូលជា {0}",
  "Sync now": "ធ្វើសមកាលកម្មឥឡូវនេះ",
  "Your changes are kept here, and merged into your account once it is paired again.": "ការផ្លាស់ប្តូររបស់អ្នកត្រូវបានរក្សាទុកនៅទីនេះ ហើយបញ្ចូលទៅក្នុងគណនីរបស់អ្នកនៅពេលដែលវ���ត្រូវបានផ្គូផ្គងម្តងទៀត។",
  "Your changes are kept here, and merged into your account once you are signed in again.": "ការផ្លាស់ប្តូររបស់អ្នកត្រូវបានរក្សាទុកនៅទីនេះ ហើយបញ្ចូលទៅក្នុងគណនីរបស់អ្នកនៅពេលដែលអ្នកបានចូលម្តងទៀត។",
  "Changes kept for {0}": "ការ​ផ្លាស់​ប្តូ​រ​បាន​រក្សា​ទុក​សម្រាប់ {0}",
  "Added back when this device connects as that account again.": "បានបន្ថែមមកវិញនៅពេលដែលឧបករណ៍នេះភ្ជាប់ជាគណនីនោះម្តងទៀត។",
  "The changes your server has not seen are kept on this device, and added back when it connects as this account again.": "ការផ្លាស់ប្តូរដែលម៉ាស៊ីនមេរបស់អ្នកមិនបានឃើញត្រូវបានរក្សាទុកនៅលើឧបករណ៍នេះ ហើយបានបន្ថែមមកវិញនៅពេលដែលវាភ្ជាប់ជាគណនីនេះម្តងទៀត។",
  "This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.": "ទូរសព្ទ​នេះ​ប្ដូរ​ទៅ​ប្រើ​តែ​ក្នុង​ស្រុក​វិញ ហើយ​ច្បាប់​ចម្លង​គណនី​របស់​អ្នក​ត្រូវ​បាន​លុប​ចេញ។ ដំបូងវាពិនិត្យមើលថាម៉ាស៊ីនមេរបស់អ្នកមានរាល់ការផ្លាស់ប្តូរ។ បើមិនដូច្នោះទេ អ្នកជ្រើសរើសអ្វីដែលកើតឡើងចំពោះពួកគេ។",
  "Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.": "ទិន្នន័យរបស់អ្នកត្រូវបានយកចេញពីកម្មវិធីរុករកនេះ; ប្រវត្តិរូបរបស់អ្នកនៅលើម៉ាស៊ីនមេរក្សាវា។ ដំបូងវាពិនិត្យមើលថាម៉ាស៊ីនមេមានការផ្លាស់ប្តូរទាំងអស់។ បើមិនដូច្នោះទេ អ្នកជ្រើសរើសអ្វីដែលកើតឡើងចំពោះពួកគេ។",
  "Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.": "ចុះហត្ថលេខាលើកម្រងព័ត៌មាននេះនៅលើគ្រប់ឧបករណ៍ រួមទាំងកម្មវិធីនេះផងដែរ។ ទូរសព្ទ​ដែល​ផ្គូផ្គង​ជាមួយ​វា​ត្រូវ​បាន​ផ្ដាច់ ហើយ​ត្រូវ​ផ្គូផ្គង​ម្ដង​ទៀត។ លេខសម្ងាត់របស់អ្នកនៅតែដំណើរការ ដូច្នេះអ្នកអាចចូលគណនីម្តងទៀតបានគ្រប់ពេល។",
