  "No weight logged last time. Enter what you lift and progression takes it from there.": "គ្មានទម្ងន់ដែលបានកត់ត្រាកាលពីលើកមុនទេ។ បញ្ចូលអ្វីដែលអ្នកលើក ហើយដំណើរការយកវាពីទីនោះ។",
