  "Could not reach {0}. Check the address and that this phone can reach it.": "មិនអាចទៅដល់ {0} បានទេ។ សូមពិនិត្យមើលអាសយដ្ឋាន ហើយទូរស័ព្ទនេះអាចទៅដល់វាបាន។",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "ចុងបញ្ចប់នៃការសម្រាក ឬការសង្កត់សំឡេងរោទ៍ដូចជាសំឡេងរោទិ៍ សូម្បីតែនៅក្នុងរបៀបស្ងាត់ក៏ដោយ។",
