  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym មិនអាចសរសេរទៅថតដែលបានជ្រើសរើសទៀតទេ ដូច្នេះចម្លងទៅកាន់ Documents/openGym ម្តងទៀត។ ជ្រើសរើសថតម្តងទៀតដើម្បីប្តូរមកវិញ។",
