  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "មួយរំពេចនៅពេលល្ងាចនៃថ្ងៃដែលបានគ្រោងទុកដោយមិនមានកំណត់ហេតុអ្វីទាំងអស់ ចន្លោះ��៉ោង 20:00 ដល់ 21:30 ។ បន្ទាប់ពីខកខាន 3 ថ្ងៃជាប់ៗគ្នា វាស្ងប់ស្ងាត់រហូតដល់ការហាត់ប្រាណបន្ទាប់របស់អ្នក។",
