  "Rough day? {0} will keep. Tomorrow is a fresh start.": "ថ្ងៃលំបាក? {0} នឹងរក្សា។ ថ្ងៃស្អែកគឺជាការចាប់ផ្តើមថ្មី។",
  "Hey, {0} didn’t happen today. All good?": "ហេ! {0} មិនបានកើតឡើងនៅថ្ងៃនេះទេ។ ល្អទាំងអស់?",
  "I miss you": "ខ្ញុំនឹកអ្នក",
