  "The barbell asked about you today. I didn’t know what to say.": "barbell បានសួរអំពីអ្នកនៅថ្ងៃនេះ។ ខ្ញុំមិនដឹងថាត្រូវនិយាយអ្វីទេ។",
  "Was it something I said? {0} misses you.": "តើវាជាអ្វីដែលខ្ញុំបាននិយាយទេ? {0} នឹក​អ្នក",
  "I saved you a spot on the bench. It’s still empty.": "ខ្ញុំបានរក្សាទុកអ្នកនៅលើកៅអី។ វានៅតែទទេ។",
