  "{0} doesn’t do itself, recruit. Move it!": "{0} មិនធ្វើដោយខ្លួនឯងទេ ជ្រើសរើស។ ផ្លាស់ទីវា!",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "លេស​មិន​លើក​ទម្ងន់។ រាយការណ៍សម្រាប់ {0} ថ្ងៃស្អែក!",
  "Your muscles filed a missing-person report. Show up for {0}!": "សាច់ដុំរបស់អ្នកបានដាក់របាយការណ៍អ្នកបាត់ខ្លួន។ បង្ហាញខ្លួនសម្រាប់ {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "អាសយដ្ឋាននោះឆ្លើយ ប៉ុន្តែវាមិនមែនជាម៉ាស៊ីនមេ OpenGym ទ��។ ពិនិត្យ URL ។",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "អាសយដ្ឋាននោះឆ្លើយតប ប៉ុន្តែទំព័រចូល ឬច្បាប់ប្រូកស៊ីបានឆ្លើយតបជំនួសឱ្យ openGym ។ អនុញ្ញាតឱ្យ /api/ ឆ្លងកាត់ទៅ openGym មិនផ្លាស់ប្តូរ។ សូមមើល \"កម្មវិធីទូរស័ព្ទ និង CORS\" នៅក្នុង docs/SELF_HOSTING.md ។",
  "Switch sides": "ប្តូរជ្រុង",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "រក្សាទុកច្បាប់ចម្លងដែលចុះកាលបរិច្ឆេទទៅ “{0}” បន្ទាប់ពីបញ្ចប់ការហាត់ប្រាណ ឬកែសម្រួលទម្លាប់ ហើយរក្សា {1} ថ្មីបំផុត។",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "រក្សាទុកច្បាប់ចម្លងដែលចុះកាលបរិច្ឆេទទៅក្នុងថតដែលអ្នកបានជ្រើសរើសបន្ទាប់ពីបញ្ចប់ការហាត់ប្រាណ ឬកែសម្រួលទម្លាប់ ហើយរក្សា {0} ថ្មីបំផុត។",
