  "Your routines in a loop": "ទម្លាប់របស់អ្នកនៅក្នុងរង្វង់មួយ",
  "Back to a fixed week?": "ត្រលប់ទៅសប្តាហ៍ថេរ?",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "រង្វិលជុំឈប់។ ថ្ងៃធ្វើការរបស់អ្នកនៅដដែល ហើយរង្វិលជុំត្រូវបានរក្សាទុកសម្រាប់ពេលក្រោយ។",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "ទម្លាប់នៅក្នុងរង្វិលជុំ។ អ្វី​ដែល​ជា​បន្ទាប់​គឺ​នៅ​បន្ទ���ប់​រហូត​ដល់​អ្នក​ហ្វឹកហាត់​វា ទោះ​ជា​ថ្ងៃ​ណា​ក៏​ដោយ។",
  "The same routines on the same weekdays, every week.": "ទម្លាប់ដូចគ្នានៅថ្ងៃធ្វើការដូចគ្នា រៀងរាល់សប្តាហ៍។",
