  "Trained out of order? Just pick another routine on Home.": "បង្វឹក​ចេញ​តាម​លំដាប់? គ្រាន់តែជ្រើសរើសទម្លាប់មួយផ្សេងទៀតនៅលើទំព័រដើម។",
  "Start the loop over": "ចាប់ផ្តើមរង្វិលជុំ",
  "Start the loop": "ចាប់ផ្តើមរង្វិលជុំ",
