  "Now in Stats, next to Muscle balance": "ឥឡូវនេះនៅក្នុងស្ថិតិ នៅជាប់នឹងសាច់ដុំតុល្យភាព",
  "Tap to plan something": "ប៉ះដើម្បីរៀបចំផែនការអ្វីមួយ",
  "Drag to reorder": "អូសដើម្បីតម្រៀបឡើងវិញ",
