  "Pick one routine, or more to train them together.": "ជ្រើសរើសទម្លាប់មួយ ឬច្រើនជាងនេះ ដើម្បីបណ្តុះបណ្តាលពួកគេជាមួយគ្នា។",
  "Planned sets per week, from your plan.": "សំណុំដែលបានគ្រោងទុកក្នុងមួយសប្តាហ៍ ពីផែនការរបស់អ្នក។",
