  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "បញ្ចូលលេខកូដដែលឧបករណ៍ផ្សេងទៀតរបស់អ្នកបង្ហាញនៅក្រោម ការកំណត់ → គណនី → បន្ថែមឧបករណ៍ផ្សេងទៀត។ បន្ទាប់មកឧបករណ៍នេះទទួលបានលេខសម្ងាត់ដោយខ្លួនឯង។",
