  "Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ផែនការ កំណត់ចំណាំ ឬកាតហាត់ប្រាណរបស់អ្នកនៅលើឧបករណ៍នេះត្រូវបានតំឡើង ខណៈពេលដែលចេញពីគណនី។ បន្ថែមពួកវាទៅក្នុងកម្រងព័ត៌មានរបស់អ្នក ឬរក្សាទម្រង់ពិតប្រាកដដូចដែលមាននៅលើម៉ាស៊ីនមេ។",
