  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ទម្លាប់ {0} ត្រូវបានធ្វើឡើងនៅលើឧបករណ៍នេះ ពេលចេញពីគណនី។ បន្ថែមពួកវាទៅក្នុងកម្រងព័ត៌មានរបស់អ្នក ឬរក្សាទម្រង់ពិតប្រាកដដូចដែលមាននៅលើម៉ាស៊ីនមេ។",
