  "Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.": "http:// ធម្មតាមិនត្រូវបានអ៊ិនគ្រីបទេ។ ជាការប្រសើរណាស់នៅលើបណ្តាញផ្ទះរបស់អ្នក ប៉ុន្តែប្រើ https:// ប្រសិនបើម៉ាស៊ីនមេរបស់អ្នកអាចទៅដល់បានពីអ៊ីនធឺណិត។",
  "Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.": "មិន​អាច​ទាក់ទង {0} តាម https:// ។ ប្រសិនបើម៉ាស៊ីនមេរបស់អ្នកដំណើរការលើ http ធម្មតា (ជាទូទៅនៅផ្ទះ) សូមវាយ http://{0} ជំនួសវិញ។",
  "Collapse completed exercises": "បង្រួមលំហាត់ដែលបានបញ្ចប់",
