  "Open Health Connect": "បើក Health Connect",
  "Install Health Connect to share workouts and weigh-ins with other apps.": "ដំឡើង Health Connect ដើម្បីចែករំលែកការហាត់ប្រាណ និងថ្លឹងទម្ងន់ជាមួយកម្មវិធីផ្សេងទៀត។",
  "Update Health Connect to share workouts and weigh-ins with other apps.": "អាប់ដេត Health Connect ដើម្បីចែករំលែកការហាត់ប្រាណ និងថ្លឹងទម្ងន់ជាមួយកម្មវិធីផ្សេងទៀត។",
  "Permission withdrawn. Tap to allow again": "ការអនុញ្ញាតត្រូវបានដកចេញ។ ប៉ះដើម្បីអនុញ្ញាតម្តងទៀត",
  "Workouts and weigh-ins go to Health Connect when you finish or change them. openGym reads nothing back.": "ការហាត់ប្រាណ និងការថ្លឹងថ្លែងទៅកាន់ Health Connect នៅពេលអ្នកបញ្ចប់ ឬផ្លាស់ប្តូ���វា។ openGym មិនអានអ្វីមកវិញទេ។",
  "Health Connect permission not granted": "មិនទាន់បានផ្តល់សិទ្ធិប្រើ Health Connect នៅឡើយទេ",
  "Could not write to Health Connect": "មិនអាចផ្ញើទិន្នន័យទៅកាន់ Health Connect បានទេ",
