  "What openGym already wrote can stay in Health Connect as your data, or be removed from it.": "អ្វីដែល openGym បានសរសេររួចហើយអាចស្ថិតនៅក្នុង Health Connect ជាទិន្នន័យរបស់អ្នក ឬត្រូវបានដកចេញពីវា។",
  "Stop, keep what it wrote": "ឈប់ រក្សាអ្វីដែលវាសរសេរ",
  "Stop and remove what it wrote": "ឈប់ ហើយ​លុប​អ្វី​ដែល​សរសេរ​ចេញ",
  "Could not remove it from Health Connect": "មិនអាចលុបទិន្នន័យចេញពី Health Connect បានទេ",
  "e.g. “swap the squats for split squats, and Mondays are short”": "ឧ. \"ផ្លាស់ប្តូរ squats សម្រាប់ squats បំបែក, ហើយថ្ងៃច័ន្ទគឺខ្លី\"",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, and you can still change any of them mid-session.": "បន្ថែមមុនពេលការងាររបស់អ្នកកំណត់ ហើយបានចាកចេញពីបរិមាណហ្វឹកហាត់ កំណត់ត្រា និងដំណើរការ។ នីមួយៗបិទចន្លោះពាក់កណ្តាលទៅនឹងទម្ងន់ការងារ ហើយអ្នកនៅតែអាចផ្លាស់ប្តូរណាមួយក្នុងចំណោមពួកគេពាក់កណ្តាលវគ្គ។",
  "The app can only pair with an https:// address. Your phone blocks plain http:// before anything is even sent.": "កម្មវិធីអាចផ្គូផ្គងជាមួយអាសយដ្ឋាន https:// ប៉ុណ្ណោះ។ ទូរសព្ទរបស់អ្នករារាំង http:// ធម្មតា មុនពេលអ្វីៗត្រូវបានផ្ញើ។",
  "Sounds": "សំឡេង",
  "Weight history keeps its numbers when units change. Body measurements are safely converted between cm and in.": "ប្រវត្តិទម្ងន់រក្សាលេខរបស់វា នៅពេលដែលគ្រឿងផ្លាស់ប្តូរ។ ការវាស់វែងរាងកាយត្រូវបានបំប្លែងដោយសុវត្ថិភាពរវាងសង់ទីម៉ែត្រ និងក្នុង។",
