  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "សិតចុងក្រោយហាត់រហូតដល់អស់កម្លាំងពីខ្លួន ហើយរាប់ជាការខិតខំប្រឹងប្រែងអស់ពីសមត្ថភាព លុះត្រាតែអ្នកវាយតម្លៃវា។",
  "Plan the final set as an all-out one.": "កំណត់សិតចុងក្រោយជាសិតហាត់អស់ពីសមត្ថភាព។",
  "Triple progression": "វឌ្ឍនភាពបីជាន់ (Triple progression)",
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "ដងឡើងដល់កំពូលនៃជួរ បន្ទាប់មកសំណុំមួយត្រូវបានបន្ថែម រហូតដល់ឈុតភាគច្រើនរបស់អ្នក។ ពួកគេទាំងអស់នៅលើកំពូល ហើយទម្ងន់នឹងឡើង ត្រឡប់ទៅឈុតដំបូងរបស់អ្នក និងតំណាងវិញ។",
  "Same weight, aim for {0} reps in every set.": "ទម្ងន់ដូចគ្នា មានបំណងសម្រាប់ {0} តំណាងនៅក្នុងរាល់ឈុត។",
  "Same weight, aim for {0} reps on the last set.": "ទម���ងន់ដូចគ្នា មានបំណងសម្រាប់ {0} ដងនៅលើឈុតចុងក្រោយ។",
  "{0} reps in every set! Add a set at {1} reps.": "តំណាង {0} ដងក្នុងឈុតនីមួយៗ! បន្ថែមសំណុំមួយនៅ {1} ដង។",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "កំពូលជួរនៅលើឈុតទាំងអស់ {0} ។ {1} {2} ទៀត ត្រលប់ទៅ {3} សំណុំនៃ {4} ។",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "កំពូលជួរនៅលើឈុតទាំងអស់ {0} ។ ជំនួយតិច {1} {2} ត្រឡប់ទៅ {3} សំណុំនៃ {4} ។",
  "Short of the target, but more reps than before. Same sets and reps again.": "ខ្លី​នៃ​គោល​ដៅ ប៉ុន្តែ​មាន​ចំនួន​ច្រើន​ជាង​មុន។ ឈុតដូចគ្នា និងធ្វើម្តងទៀត។",
  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "ខ���ខានដងកាលពីលើកមុន។ សំណុំដូចគ្នា និងធ្វើម្តងទៀតម្តងទៀត ({0} នៃ {1} ដែលត្រូវទៅ)។",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "ជាប់គាំងសម្រាប់ {0} វគ្គ។ ផ្ទុកទៅ {1} {2} ហើយចាប់ផ្តើមម្តងទៀតនៅ {3} សំណុំនៃ {4} ។",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "ជាប់គាំងសម្រាប់ {0} វគ្គ។ ត្រឡប់ទៅ {1} {2} នៃជំនួយ ចាប់ផ្តើមម្តងទៀតនៅ {3} សំណុំនៃ {4} ។",
  "Sets from": "ចំនួនសិតចាប់ពី",
  "Sets up to": "ចំនួនសិតរហូតដល់",
  "Exercises in this workout": "លំហាត់នៅក្នុងលំហាត់នេះ",
