  "Exercise chips at the top": "ប៊ូតុងមូលជ្រើសរើសលំហាត់នៅខាងលើ",
  "A numbered dot per exercise, filled as you go. Tap one to jump there.": "ចំណុចដែលមានលេខក្នុងមួយលំហាត់ បំពេញនៅពេលអ្នកទៅ។ ចុចមួយដើម្បីលោតនៅទីនោះ។",
