  "Sick": "ឈឺ",
  "Travelling": "ធ្វើដំណើរ",
  "Injured": "រងរបួស",
  "Day note": "កំណត់ចំណាំប្រចាំថ្ងៃ",
  "Add a note for this day": "បន្ថែមកំណត់ចំណាំសម្រាប់ថ្ងៃនេះ",
  "Noted. See you next session!": "បានកត់ត្រាទុក។ ជួបគ្នាវគ្គបន្ទាប់!",
  "Note removed": "បានលុបកំណត់ចំណាំ",
  "Remove note": "លុបកំណត់ចំណាំ",
  "Life happens. Leave yourself a note, and the missed-day nudge lets this one go.": "ជីវិតកើតឡើង។ ទុក​ឱ្យ​ខ្លួន​អ្នក​នូវ​កំណត់​ត្រា​មួយ ហើយ​ការ​ខក​ខាន​ថ្ងៃ​នេះ​អនុញ្ញាត​ឱ្យ​មួយ​នេះ​ទៅ​។",
  "Anything else? (optional)": "មានអ្វីផ្សេងទៀត? (ស្រេចចិត្ត)",
  "Bell": "កណ្តឹង",
