  "Your sports watch, calling you back.": "នាឡិកាកីឡារបស់អ្នក កំពុងរំលឹកអ្នកឱ្យត្រឡប់មកហាត់វិញ។",
  "Coach wants you back on the bar.": "គ្រូបង្វឹកចង់ឱ្យអ្នកត្រឡប់មកកាន់ដុំដែកហាត់វិញ។",
  "Gentle, for headphones or a quiet room.": "សំឡេងស្រាល សម្រាប់កាសស្តាប់ ឬបន្ទប់ស្ងប់ស្ងាត់។",
